"use strict";(globalThis.webpackChunknative_update_docs=globalThis.webpackChunknative_update_docs||[]).push([[5719],{26278(e){e.exports=JSON.parse('{"groups":[{"kind":"docs","key":"docs","pages":[{"permalink":"/intro","title":"Introduction","description":"native-update is a Capacitor plugin that ships over-the-air JavaScript bundle updates, in-app store update prompts, and native review prompts to mobile apps without rebuilding or resubmitting them.","tags":[]},{"permalink":"/ai-integration","title":"AI Integration Guide","description":"Quick reference for AI development agents integrating native-update.","tags":[]},{"permalink":"/changelog","title":"Changelog","description":"Release history for the native-update plugin.","tags":[]},{"permalink":"/backend/plans-and-limits","title":"Plans, limits and update delivery","description":"What happens on the hosted Native Update service when an account goes over its plan\'s app or monthly active user limit, how update delivery pauses after a 7-day grace period, and what your app\'s users see.","tags":[]}]},{"kind":"category","key":"/getting-started/installation","label":"Getting Started","pages":[{"permalink":"/getting-started/installation","title":"Installation","description":"Install the native-update Capacitor plugin into a new or existing Capacitor 8 project. Covers npm install, iOS pod install, Android sync, and verification.","tags":[]},{"permalink":"/getting-started/quick-start","title":"Quick Start","description":"Ship your first OTA update with native-update in five minutes \u2014 install, configure, sync, and listen for download progress events.","tags":[]}]},{"kind":"category","key":"/dashboard/ai-assistants","label":"Dashboard","pages":[{"permalink":"/dashboard/ai-assistants","title":"AI assistants and Speak","description":"The two dashboard assistants. The release notes writer drafts a release\'s notes and changelog from what you type or say; the docs assistant answers setup questions from these docs and names the page it used.","tags":[]},{"permalink":"/dashboard/jobs","title":"Jobs page","description":"Every slow piece of work in the dashboard runs as a job \u2014 bundle processing, release notes drafts and docs assistant answers. The Jobs page shows each one\'s status, attempts and errors.","tags":[]},{"permalink":"/dashboard/referrals","title":"Referrals","description":"Share your referral link. When someone signs up with it and verifies their email, you earn points and a dated badge, and every few confirmed referrals add a month of Pro.","tags":[]},{"permalink":"/dashboard/support","title":"Support Native Update","description":"A choose-your-price payment, one time or monthly, that helps keep Native Update running. It needs no account and does not change your plan.","tags":[]}]},{"kind":"category","key":"/reference/sdk/live-update/overview","label":"SDK Reference","pages":[{"permalink":"/reference/sdk/live-update/overview","title":"Live Update \u2014 Overview","description":"The Live Update API ships JavaScript bundles to installed Capacitor apps over the air. Read this first before diving into method, type, enum, event, or config reference pages.","tags":[]},{"permalink":"/reference/sdk/live-update/methods","title":"Live Update \u2014 Methods","description":"Complete reference for all 20 Live Update API methods in native-update. Each entry includes the TypeScript signature, parameters, return value, errors thrown, and a runnable example.","tags":[]},{"permalink":"/reference/sdk/live-update/types","title":"Live Update \u2014 Types","description":"TypeScript type reference for the Live Update API of native-update. Field-by-field breakdown of BundleInfo, SyncOptions, SyncResult, DownloadOptions, LatestVersion, CheckForUpdateResult, DownloadUpdateOptions, ValidateOptions, ValidationResult, and DeleteOptions.","tags":[]},{"permalink":"/reference/sdk/live-update/enums","title":"Live Update \u2014 Enums","description":"Enum reference for the Live Update API of native-update \u2014 UpdateStrategy, UpdateMode, ChecksumAlgorithm, SyncStatus, BundleStatus, and the Live-Update-relevant subset of UpdateErrorCode.","tags":[]},{"permalink":"/reference/sdk/live-update/events","title":"Live Update \u2014 Events","description":"Event reference for the Live Update API of native-update \u2014 downloadProgress and updateStateChanged. Includes payload shapes, when they fire, and a complete listener-and-cleanup pattern.","tags":[]},{"permalink":"/reference/sdk/live-update/config","title":"Live Update \u2014 Config","description":"Field-by-field reference for LiveUpdateConfig \u2014 every option that controls Live Update behaviour at initialise time, with defaults, types, and recommended production values.","tags":[]},{"permalink":"/reference/sdk/app-update/overview","title":"App Update \u2014 Overview","description":"The App Update API of native-update wraps Google Play In-App Updates and the iOS App Store version check behind one cross-platform interface, letting your Capacitor app prompt users to update the binary from inside the app.","tags":[]},{"permalink":"/reference/sdk/app-update/methods","title":"App Update \u2014 Methods","description":"Reference for all 5 App Update API methods in native-update \u2014 getAppUpdateInfo, performImmediateUpdate, startFlexibleUpdate, completeFlexibleUpdate, openAppStore. Each entry includes signature, parameters, errors, and a runnable example.","tags":[]},{"permalink":"/reference/sdk/app-update/types","title":"App Update \u2014 Types","description":"TypeScript type reference for the App Update API of native-update \u2014 AppUpdateInfo and OpenAppStoreOptions, with field-by-field tables and example payloads.","tags":[]},{"permalink":"/reference/sdk/app-update/events","title":"App Update \u2014 Events","description":"Event reference for the App Update API of native-update \u2014 appUpdateStateChanged, appUpdateProgress, appUpdateAvailable, appUpdateReady, appUpdateFailed, appUpdateNotificationClicked, appUpdateInstallClicked. Includes payload shapes, fire conditions, and the InstallStatus enum.","tags":[]},{"permalink":"/reference/sdk/app-update/config","title":"App Update \u2014 Config","description":"Field-by-field reference for AppUpdateConfig \u2014 every option that controls App Update behaviour at initialise time.","tags":[]},{"permalink":"/reference/sdk/app-review/overview","title":"App Review \u2014 Overview","description":"The App Review API of native-update wraps Google Play In-App Review and Apple SKStoreReviewController behind one cross-platform interface, with sensible default throttling so you never burn the user\'s once-per-quarter system limit.","tags":[]},{"permalink":"/reference/sdk/app-review/methods","title":"App Review \u2014 Methods","description":"Reference for the two App Review API methods in native-update \u2014 requestReview and canRequestReview. Includes signatures, return types (ReviewResult and CanRequestReviewResult), and a complete usage pattern.","tags":[]},{"permalink":"/reference/sdk/app-review/config","title":"App Review \u2014 Config","description":"Field-by-field reference for AppReviewConfig \u2014 every option that controls App Review throttling, custom triggers, debug mode, and web fallback URL.","tags":[]},{"permalink":"/reference/sdk/background-update/overview","title":"Background Update \u2014 Overview","description":"The Background Update API of native-update runs battery-aware and network-aware silent update checks while your Capacitor app is closed, with optional native notifications when an update is found or installed.","tags":[]},{"permalink":"/reference/sdk/background-update/methods","title":"Background Update \u2014 Methods","description":"Reference for all 8 Background Update API methods in native-update \u2014 enable/disable, status, schedule, trigger, plus notification preferences and permissions.","tags":[]},{"permalink":"/reference/sdk/background-update/config","title":"Background Update \u2014 Config","description":"Field-by-field reference for BackgroundUpdateConfig and NotificationPreferences \u2014 every option that controls scheduled silent updates and the notifications they post.","tags":[]},{"permalink":"/reference/sdk/background-update/events","title":"Background Update \u2014 Events","description":"Event reference for the Background Update API of native-update \u2014 backgroundUpdateProgress and backgroundUpdateNotification, with payload shapes and usage patterns.","tags":[]},{"permalink":"/reference/sdk/security/overview","title":"Security \u2014 Overview","description":"Security primitives in native-update \u2014 getSecurityInfo, SecurityConfig, certificate pinning, and the full UpdateErrorCode catalogue. Covers HTTPS enforcement, bundle signing, and input validation.","tags":[]},{"permalink":"/reference/sdk/security/error-codes","title":"Security \u2014 Error Codes","description":"Complete UpdateErrorCode catalogue for native-update \u2014 every code that can be thrown across Live Update, App Update, App Review, Background Update, and Security flows, grouped by domain with recommended remediation.","tags":[]},{"permalink":"/reference/sdk/security/certificate-pinning","title":"Security \u2014 Certificate Pinning","description":"Reference for the CertificatePinning and CertificatePin types in native-update plus a working OpenSSL recipe to extract SHA-256 pins from your update server\'s TLS certificate.","tags":[]},{"permalink":"/reference/sdk/core/lifecycle","title":"Core \u2014 Lifecycle","description":"Reference for the core lifecycle methods of native-update \u2014 initialize, isInitialized, configure, reset, cleanup. Covers what each does, when to call it, and the ordering rules between them.","tags":[]},{"permalink":"/reference/sdk/core/config","title":"Core \u2014 Config (PluginInitConfig)","description":"Field-by-field reference for PluginInitConfig \u2014 the single configuration object passed to NativeUpdate.initialize() at app boot. Covers every flag across server, security, live-update, app-update, and review settings.","tags":[]}]},{"kind":"category","key":"/reference/cli/overview","label":"CLI Reference","pages":[{"permalink":"/reference/cli/overview","title":"CLI \u2014 Overview","description":"The native-update CLI ships with the npm package and provides project bootstrap, key-pair generation, bundle creation, signing, verification, a local dev server, deployment monitoring, and backend scaffolds. Read this first.","tags":[]},{"permalink":"/reference/cli/init","title":"init \u2014 Scaffold native-update config","description":"native-update init scaffolds a native-update.config.js file by prompting for app ID, server URL, default channel, and auto-update. Optional --example flag writes a working integration snippet.","tags":[]},{"permalink":"/reference/cli/keys-generate","title":"keys generate \u2014 Generate signing key pair","description":"native-update keys generate produces an RSA-2048 or RSA-4096 key pair for RSA-SHA256 bundle signing. The private key is chmod 600; the public key goes into your app\'s native-update config.","tags":[]},{"permalink":"/reference/cli/bundle-create","title":"bundle create \u2014 Package a web build into an OTA bundle","description":"native-update bundle create packages your built web directory (./dist, ./www, etc.) into a versioned ZIP plus a JSON metadata file with SHA-256 checksum, channel, and arbitrary release notes.","tags":[]},{"permalink":"/reference/cli/bundle-sign","title":"bundle sign \u2014 Sign an OTA bundle with your private key","description":"native-update bundle sign produces an RSA-SHA256 signature of an OTA bundle and writes a sidecar .sig JSON file. The signed bundle and signature both upload to your backend; the device-side SDK verifies before applying.","tags":[]},{"permalink":"/reference/cli/bundle-verify","title":"bundle verify \u2014 Verify a signed bundle with your public key","description":"native-update bundle verify confirms an OTA bundle\'s RSA-SHA256 signature against your public key. Use it as a CI safety net before uploading \u2014 exits 1 if the signature is invalid.","tags":[]},{"permalink":"/reference/cli/server-start","title":"server start \u2014 Run a local dev update server","description":"native-update server start runs a tiny Express server that serves bundles from a local directory. Designed for testing the device-side sync flow against your own machine before deploying a real backend.","tags":[]},{"permalink":"/reference/cli/monitor","title":"monitor \u2014 Watch live deployment stats","description":"native-update monitor polls a backend\'s /api/stats endpoint every 5 seconds and renders a terminal dashboard with current version, channel, download totals, and recent activity. Useful for tracking a rollout in real time.","tags":[]},{"permalink":"/reference/cli/backend-create","title":"backend create \u2014 Scaffold an Express, Firebase, or Vercel backend","description":"native-update backend create generates a starter Express / Firebase Functions / Vercel serverless backend with the HTTP contract the SDK expects. The output is a SCAFFOLD with TODO[SCAFFOLD-IMPLEMENT-BEFORE-DEPLOY] markers \u2014 not production-ready.","tags":[]},{"permalink":"/reference/cli/deploy","title":"CLI \u2014 deploy & remote commands","description":"Deploy a bundle from CI or your terminal with an access token \u2014 deploy, apps list, builds list/promote/rollout/status/delete, jobs status, and token info.","tags":[]}]},{"kind":"category","key":"/public-api/overview","label":"Public API","pages":[{"permalink":"/public-api/overview","title":"Public API \u2014 Overview","description":"Manage your apps, builds, and releases over HTTP with a personal access token. Deploy from CI, a script, or an AI agent \u2014 the same things the dashboard does.","tags":[]},{"permalink":"/public-api/endpoints","title":"Public API \u2014 Endpoints","description":"Every route on the public management API, with curl examples \u2014 token introspection, app CRUD, API keys, signing keys, keystore backup, builds, upload, promote, rollout, delete, and job status.","tags":[]},{"permalink":"/public-api/async-jobs","title":"Public API \u2014 Queued jobs","description":"Uploads return 202 with a job id. How the job lifecycle works, how to poll it, and what happens when processing fails.","tags":[]}]},{"kind":"category","key":"/backend/overview","label":"Backend","pages":[{"permalink":"/backend/overview","title":"Backend \u2014 Overview","description":"native-update needs a backend that serves bundle metadata and the bundle ZIP. Use the hosted Native Update service, or your own server that implements the documented contract. This page helps you pick.","tags":[]},{"permalink":"/backend/node-express-minimal","title":"Node + Express Minimal Backend","description":"The example-apps/node-express reference is the smallest backend that implements the native-update HTTP contract. ~160 lines of Express + multer, JSON-file metadata, no auth, no signing \u2014 meant to be read in one sitting and adapted.","tags":[]},{"permalink":"/backend/api-contract","title":"API Contract","description":"The exact HTTP contract every native-update backend must satisfy. Six endpoints, full request and response shapes, authentication, status codes, error envelopes, and the field semantics the SDK enforces.","tags":[]}]},{"kind":"category","key":"/platforms/android","label":"Platforms","pages":[{"permalink":"/platforms/android","title":"Android Platform Guide","description":"Everything you need to wire native-update into an Android Capacitor app \u2014 required permissions, manifest additions for background updates, WorkManager constraints, Play Core integration, ProGuard rules, signing setup, and Play Console-compliance pitfalls.","tags":[]},{"permalink":"/platforms/ios","title":"iOS Platform Guide","description":"Everything you need to wire native-update into an iOS Capacitor app \u2014 Info.plist keys, BGTaskScheduler permitted identifiers, background mode capabilities, ATS exceptions, SKStoreReviewController throttling, keychain usage, App Store Review guideline compliance, privacy manifest entries.","tags":[]},{"permalink":"/platforms/web","title":"Web Platform Guide","description":"What native-update can and cannot do when running in a browser, the service-worker-based update fallback, and when the web target is actually useful (browser dev fallback for Capacitor, PWA-style update prompts, automated tests).","tags":[]}]},{"kind":"category","key":"/tutorials/first-ota-update","label":"Tutorials","pages":[{"permalink":"/tutorials/first-ota-update","title":"Your first OTA update \u2014 end to end","description":"A step-by-step walkthrough from a fresh Capacitor project to a verified OTA update applied on a real device. Covers install, signing-key generation, bundle creation, signing, upload, the device-side sync, and verifying the new bundle ran.","tags":[]}]},{"kind":"category","key":"/how-to/manage-channels","label":"How-to guides","pages":[{"permalink":"/how-to/manage-channels","title":"Manage release channels","description":"How to use channels (production, staging, beta, canary) to route different bundle versions to different cohorts of devices without changing your app\'s code.","tags":[]},{"permalink":"/how-to/restrict-api-keys","title":"Restrict an API key to your app (ship the key safely)","description":"Lock a native-update API key to specific web origins, Android apps (package + signing certificate), and iOS bundle ids so it can be shipped inside your app without a proxy server of your own. Covers the dashboard flow, getting signing-cert fingerprints with keytool, the plugin version requirement, and what the restrictions do and do not protect.","tags":[]},{"permalink":"/how-to/rotate-signing-keys","title":"Rotate signing keys without breaking active bundles","description":"How to introduce a new bundle-signing keypair while keeping bundles signed by the old key verifiable on existing devices. Covers the multi-key transition window, the dashboard\'s rotation flow, and the emergency revoke path for a leaked private key.","tags":[]},{"permalink":"/how-to/roll-back-bundle","title":"Roll back a bad bundle","description":"How to revert devices to a previous bundle after a bad release. Covers the automatic crash-rollback, the server-side rollout-throttle path, and the explicit per-device rollback API.","tags":[]},{"permalink":"/how-to/migrate-from-codepush","title":"Migrate from CodePush","description":"A practical migration guide from Microsoft CodePush (App Center) to native-update. Maps CodePush concepts to native-update equivalents, covers running both side-by-side during the transition, and lists the gotchas that bite real migrations.","tags":[]},{"permalink":"/how-to/ci-cd-github-actions","title":"Integrate with CI/CD (GitHub Actions)","description":"A production-grade GitHub Actions workflow that builds, bundles, signs, verifies, and uploads an OTA release on every push to main. Covers secret management, key handling, fan-out across channels, and the manual-approval pattern for production rollouts.","tags":[]},{"permalink":"/how-to/test-bundles-locally","title":"Test bundles in development","description":"Three local-test loops for OTA bundles \u2014 the bundle-verify smoke test, the native-update server start dev server, and the full-device LAN test. Covers what each one catches, what it doesn\'t, and when to use which.","tags":[]},{"permalink":"/how-to/troubleshooting","title":"Troubleshoot updates","description":"Diagnose the most common native-update failures \u2014 updates not detected, downloads failing, installs rejected, crash rollbacks, and dashboard mismatches \u2014 with the real SDK methods.","tags":[]}]},{"kind":"category","key":"/compare","label":"Moving to Native Update","pages":[{"permalink":"/compare","title":"Moving to Native Update","description":"Which update services a Capacitor app can really move from, step by step, and which serve stacks Native Update doesn\'t. Prices and features with dated sources.","tags":[]},{"permalink":"/compare/capgo","title":"Moving from Capgo to Native Update","description":"Replace Capgo\'s updater in a Capacitor app with native-update: a signing key, one config, your first signed release, then remove the old plugin. Prices and features dated.","tags":[]},{"permalink":"/compare/capawesome-cloud","title":"Moving from Capawesome Cloud to Native Update","description":"Move a Capacitor app from Capawesome Cloud Live Updates to native-update: new signing key, new channels, one store release. Plan prices and feature rows dated.","tags":[]},{"permalink":"/compare/ionic-appflow","title":"Moving from Ionic Appflow to Native Update","description":"Ionic stopped new Appflow sales, and access ends on December 31, 2027. How to move a Capacitor app\'s live updates to native-update, and what it does not replace.","tags":[]},{"permalink":"/compare/capawesome-app-update-review","title":"From Capawesome\'s App Update and App Review plugins to Native Update","description":"Replace @capawesome/capacitor-app-update and @capawesome/capacitor-app-review with one package: the method names, the Play update flow and the store review prompt.","tags":[]},{"permalink":"/compare/expo-eas-update","title":"Expo EAS Update and Native Update","description":"EAS Update is built for Expo and React Native apps. Native Update serves Capacitor only today, so there is no move to make. Dated prices and feature rows.","tags":[]},{"permalink":"/compare/shorebird","title":"Shorebird and Native Update","description":"Shorebird patches compiled Dart in Flutter apps. Native Update ships web bundles to Capacitor apps only today, so there is no move to make. Dated prices and rows.","tags":[]},{"permalink":"/compare/revopush","title":"Revopush and Native Update","description":"Revopush keeps the CodePush SDK calls for React Native apps. Native Update serves Capacitor only today, so there is no move to make. Dated prices and rows.","tags":[]},{"permalink":"/compare/codepushgo","title":"CodePushGo and Native Update","description":"CodePushGo ships live updates to React Native apps. Native Update serves Capacitor only today, so there is no move to make. Dated prices and feature rows.","tags":[]},{"permalink":"/compare/cresc","title":"Cresc and Native Update","description":"Cresc prices React Native OTA updates by daily queries. Native Update serves Capacitor only today, so there is no move to make. Dated prices and feature rows.","tags":[]},{"permalink":"/compare/stallion","title":"Stallion and Native Update","description":"Stallion ships OTA updates to React Native apps. Native Update serves Capacitor only today, so there is no move to make. Dated prices and feature rows.","tags":[]},{"permalink":"/compare/codemagic-patch","title":"Codemagic Patch and Native Update","description":"Codemagic Patch ships OTA updates to React Native apps, hosted or self-hosted. Native Update serves Capacitor only today, so there is no move to make.","tags":[]},{"permalink":"/compare/appcircle-codepush","title":"Appcircle CodePush and Native Update","description":"Appcircle CodePush is an OTA module inside a CI/CD platform for React Native. Native Update serves Capacitor only today, so there is no move to make.","tags":[]},{"permalink":"/compare/appsonair","title":"AppsOnAir and Native Update","description":"AppsOnAir has SDKs for Android, iOS, Flutter and React Native. Native Update serves Capacitor only today, so there is no move to make. Dated prices and rows.","tags":[]},{"permalink":"/compare/hot-updater","title":"Hot Updater and Native Update","description":"Hot Updater is a self-hosted OTA updater for React Native and Expo. Native Update serves Capacitor only today, so there is no move to make. Dated facts.","tags":[]},{"permalink":"/compare/code-push-server","title":"Microsoft code-push-server and Native Update","description":"Microsoft\'s standalone CodePush server is archived. For React Native, Native Update is no replacement today; for Capacitor or Cordova, here is where to go. Dated facts.","tags":[]}]},{"kind":"category","key":"/concepts/how-ota-updates-work","label":"Concepts","pages":[{"permalink":"/concepts/how-ota-updates-work","title":"How OTA updates work","description":"A conceptual walkthrough of the over-the-air update lifecycle in native-update, from the moment you push a release to the moment the user sees the new bundle. Covers bundle creation, delivery, sync, verification, atomic apply, and rollback.","tags":[]},{"permalink":"/concepts/bundle-integrity-and-signing","title":"Bundle integrity and signing","description":"A conceptual explanation of the two-layer integrity model native-update uses for OTA bundles \u2014 SHA-256 for transit integrity and RSA-SHA256 signing for source authentication. Covers what each layer protects against, the trust chain, and the threats the model does not address.","tags":[]},{"permalink":"/concepts/update-strategies-compared","title":"Update strategies compared","description":"A side-by-side comparison of the four update strategies native-update offers \u2014 immediate, on-app-start, on-app-resume, and background \u2014 covering when each fires, what the user sees, the trade-offs, and which to default to.","tags":[]},{"permalink":"/concepts/architecture","title":"Architecture","description":"A diagrammed walkthrough of how the native-update system is layered \u2014 the CLI, the backend, the SDK runtime, the platform-native modules, and the storage tier. Includes mermaid diagrams of the build-time, deploy-time, and runtime data flows.","tags":[]},{"permalink":"/concepts/security-model","title":"Security model","description":"The threat model native-update is designed to defend against, the three layers of defense it implements (transport, content, runtime), what\'s in scope and what isn\'t, and the operational practices the model assumes you follow.","tags":[]},{"permalink":"/concepts/error-handling-philosophy","title":"Error handling philosophy","description":"Why native-update fails open on analytics writes, fails closed on signature verification, returns typed error codes, and keeps the app running through OTA failures. Explains the design principles behind the SDK\'s error surface.","tags":[]}]},{"kind":"category","key":"/about","label":"About","pages":[{"permalink":"/about","title":"About Native Update","description":"Native Update is a SaaS product for Capacitor apps, built and maintained by the Native Update team. How to reach us, and how the plugin is licensed.","tags":[]}]}],"blog":{"permalink":"/blog","title":"Native Update releases","description":"Release notes for each published version of native-update, newest first.","tags":[]},"posts":[{"permalink":"/blog/native-update-4-1-1","title":"Native Update 4.1.1","description":"Native Update 4.1.1 release notes: refreshed Capacitor 8, CLI, build, lint and test dependencies, with no change to the public plugin API.","tags":["Release"],"date":"2026-10-21"},{"permalink":"/blog/native-update-4-1-0","title":"Native Update 4.1.0","description":"Native Update 4.1.0 release notes: a locally signed bundle can now be uploaded with its signature, and deploy picks up the sibling .sig file.","tags":["Release"],"date":"2026-09-05"},{"permalink":"/blog/native-update-4-0-0","title":"Native Update 4.0.0","description":"Native Update 4.0.0 release notes: real delta delivery, Capacitor 8 and current toolchain requirements, RSA-SHA256 signatures and locked configuration.","tags":["Release"],"date":"2026-08-05"},{"permalink":"/blog/native-update-3-4-0","title":"Native Update 3.4.0","description":"Native Update 3.4.0 release notes: the full app lifecycle on the Public Management API, the all_apps token scope and new CLI commands.","tags":["Release"],"date":"2026-07-23"}]}')}}]);